// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {ModifierEntrancy} from "../src/ModifierEntrancy.sol";

contract InvMutTest is Test {
    ModifierEntrancy c;
    function setUp() public { c = new ModifierEntrancy(); }
    function testRegression_property() public {
        Bank bank = new Bank();
        address alice = address(bank);

        vm.prank(alice);
        c.airDrop();

        bool ok;
        vm.prank(alice);
        try c.airDrop() {
            ok = true;
        } catch {
            ok = false;
        }

        assertTrue(!ok, "Second call should revert in reference");
    }
}

contract Bank {
    function supportsToken() external pure returns (bytes32) {
        return keccak256(abi.encodePacked("Nu Token"));
    }
}
